import{_ as a,o as t,c as s,a5 as r}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-11-view-workspace-dashboard/report3_spec.md","filePath":"feature/agency-workspace/3-4-11-view-workspace-dashboard/report3_spec.md"}'),o={name:"feature/agency-workspace/3-4-11-view-workspace-dashboard/report3_spec.md"};function n(i,e,c,l,p,g){return t(),s("div",null,[...e[0]||(e[0]=[r("<p><strong>3.4.11 View Workspace Dashboard</strong></p><p><strong>Function Trigger</strong></p><p>Begins when a Workspace member opens the Dashboard of a Workspace.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Workspace members with role MANAGER, CREATOR, or CLIENT.</li><li><strong>Purpose</strong>: Gives members an overview of the Workspace&#39;s members, campaigns, package negotiation status, and the parent Agency&#39;s AI credit usage.</li><li><strong>Interface</strong>: Workspace dashboard screen, showing summary cards.</li><li><strong>Data Processing</strong>: The system resolves the Workspace, confirms the caller is an active member, then aggregates active member count and role breakdown, campaign count and status breakdown, the current package negotiation status, and the parent Agency&#39;s AI credit usage for the current calendar month.</li><li>No Task or Material entity exists in this codebase, so the dashboard does not show a Task summary. AI credit usage is Agency-wide, not per-Workspace, and is labeled as Agency-scoped.</li></ul><p><strong>Screen Layout</strong></p><p>Figure - Workspace Dashboard Screen:</p><ul><li>Header carrying the Workspace name.</li><li>Four stat cards in a row: Active members, Total campaigns, Package status (or &quot;No package&quot;), Agency AI credits used this month.</li><li>Two breakdown cards: Members by role, Campaigns by status - each an empty list if the Workspace has none yet.</li><li>A newly created Workspace with no package/campaign shows member counts as normal, campaign count as 0, package status as &quot;No package&quot;.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: the Workspace identifier; the caller&#39;s authenticated identity.</li><li><strong>Input optional</strong>: none.</li><li><strong>System data</strong>: active WorkspaceMember rows; the Workspace&#39;s WorkspaceMediaPackage (if any) and its MediaCampaign rows; the parent Agency&#39;s AiCreditLedger row for the current month.</li><li><strong>Output</strong>: the full Workspace profile, active member count and role breakdown, campaign count and status breakdown, package negotiation status (nullable), the Agency id, the current month string, and the Agency&#39;s AI credits used this month.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-29</strong>: Only members holding an active membership row in the Workspace may view its dashboard, enforced both at the controller and inside the service. There is no Workspace-level OWNER - OWNER exists only at Agency level.</li><li><strong>BR-03</strong>: The dashboard is read-only and changes no data.</li><li><strong>BR-04</strong>: An empty Workspace (no package, no campaigns) renders member counts normally and campaign/package fields as empty/zero/null rather than failing.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Caller must be an active member of the Workspace; otherwise 403 WORKSPACE_ACCESS_DENIED or 403 FORBIDDEN.</li><li>Workspace must exist; otherwise 404 WORKSPACE_NOT_FOUND.</li><li>A Workspace with no package/campaigns must render without error.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>Member opens the Dashboard of a Workspace.</li><li>System resolves the Workspace and confirms active membership (BR-29).</li><li>System aggregates active member count/role breakdown, campaign count/status breakdown, package negotiation status, and the Agency&#39;s current-month AI credit usage.</li><li>Screen renders the stat cards and breakdown lists; an empty Workspace shows zeros/empty lists without error.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: The Workspace does not exist -&gt; 404 WORKSPACE_NOT_FOUND, toast <strong>MSG38</strong>. 2.a2: The member returns to the Workspace list.</li><li>2.b1: Caller is not an active member of the Workspace -&gt; 403 WORKSPACE_ACCESS_DENIED or FORBIDDEN, toast <strong>MSG40</strong>. 2.b2: The member returns to the Workspace list.</li><li>3.a1: Workspace has no package yet -&gt; packageNegotiationStatus is null, totalCampaigns is 0. 3.a2: The member continues viewing the dashboard normally.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>No data is changed; the Workspace&#39;s member, campaign, package, and Agency AI credit summary is displayed.</li></ul>",14)])])}const u=a(o,[["render",n]]);export{m as __pageData,u as default};
